#include <cmath>
#include <algorithm>

class Solution {
public:
    int countKthRoots(int l, int r, int k) {
        if (k == 1) return r - l + 1;

        auto maxBase = [&](long long limit) -> long long {
            if (limit < 0) return -1;
            long long low = 0, high = std::min<long long>(limit, 1e9);
            long long best = 0;
            while (low <= high) {
                long long mid = (low + high) / 2;
                __int128 p = 1;
                bool ok = true;
                for (int i = 0; i < k; ++i) {
                    p *= mid;
                    if (p > limit) { ok = false; break; }
                }
                if (ok) {
                    best = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            return best;
        };

        long long upper = maxBase(r);
        long long lower = maxBase(l - 1);
        return std::max(0LL, upper - lower);
    }
};

class Solution {
    public int countKthRoots(int l, int r, int k) {
        if (k == 1) return r - l + 1;

        long upper = maxBase(r, k);
        long lower = maxBase(l - 1, k);
        return (int)Math.max(0, upper - lower);
    }

    private long maxBase(long limit, int k) {
        if (limit < 0) return -1;
        long low = 0, high = limit;
        long best = 0;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(mid, k, limit)) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return best;
    }

    private boolean check(long base, int k, long limit) {
        long p = 1;
        for (int i = 0; i < k; i++) {
            if (limit / base < p) return false;
            p *= base;
        }
        return p <= limit;
    }
}

function countKthRoots(l, r, k) {
    if (k === 1) return r - l + 1;

    function maxBase(limit) {
        if (limit < 0n) return -1n;
        let low = 0n, high = limit;
        let best = 0n;
        while (low <= high) {
            const mid = (low + high) / 2n;
            let p = 1n;
            let ok = true;
            for (let i = 0; i < k; i++) {
                p *= mid;
                if (p > limit) { ok = false; break; }
            }
            if (ok) {
                best = mid;
                low = mid + 1n;
            } else {
                high = mid - 1n;
            }
        }
        return best;
    }

    const upper = maxBase(BigInt(r));
    const lower = maxBase(BigInt(l - 1));
    const diff = upper - lower;
    return diff > 0n ? Number(diff) : 0;
}
